def note(page, title, short, meaning, words, references=()):
    return {'page': page, 'title': title, 'short': short, 'meaning': meaning,
            'words': words, 'references': list(references)}

def rule(title, short, meaning, references=(), notes=(), kind='recitation'):
    return {'title': title, 'short': short, 'meaning': meaning,
            'references': list(references), 'occurrenceNotes': list(notes), 'kind': kind}

def main():
    occurrences = read(PROVENANCE / 'occurrences.json')
    occurrence_map = {(x['id'], x['paint']): x for x in occurrences}
    replacements = {}
    def put(rid, color, value):
        replacements[rid, color + ':fill'] = value
    def alias(rid, color, title, references=(), notes=()):
        put(rid, color, rule(title, {'الإدغام': 'ادمج الحرفين', 'السكت': 'سكت بلا تنفّس', 'المخالفة لحفص': 'اتبع ضبط الرواية', 'مدّ البدل': 'مدّ بعد الهمز', 'مدّ اللين': 'مدّ حرف اللين', 'الراءات المرقّقة': 'رقّق الراء'}[title], FULL_MEANINGS[title], references, notes, 'source shade of documented rule'))

    alias('warsh', '#00FFFF', 'مدّ البدل', [REFS['warsh']], [note(73, 'مدّ البدل في «فآمنوا»', 'مدّ بعد الهمز', 'موضع اللون في «فآمنوا بالله ورسله»: ألف المد بعد الهمزة من مد البدل. الدرجة السماوية الأفتح هنا تؤدي وظيفة علامة البدل.', ['فآمنوا'])])
    alias('warsh', '#808000', 'مدّ اللين', [REFS['warsh']], [note(425, 'مدّ اللين في «شيئًا»', 'مدّ الياء اللينة', 'الياء في «شيئًا» ساكنة وقبلها فتحة وبعدها همزة؛ تعمل بأوجه مد اللين في طريق ورش المأخوذ به. الدرجة الزيتونية واقعة في مكونات ضبط هذه الكلمة.', ['شيئًا'])])
    alias('warsh', '#339A65', 'الراءات المرقّقة', [REFS['warsh']], [note(546, 'ترقيق راء «قدير»', 'رقّق الراء', 'رقّق الراء في «قدير». اللون الأخضر الفرعي في مكوّن ضبط الراء تابع لترقيقها في هذا الموضع.', ['قدير'])])
    put('warsh', '#008000', rule('حركات الضبط في الموضع', 'اقرأ حركة الكلمة', 'تظهر هذه الدرجة الخضراء في أجزاء ضبط متفرقة، ولا يضع لها مفتاح الناشر حكمًا عامًا مستقلًا. يُشرح الأداء لكل موضع أدناه: بعضها حركة عادية، وبعضها جزء من علامة ترقيق الراء أو البدل. لا تعاملها كلها على أنها ترقيق أو إمالة.', [REFS['warsh']], [
        note(6, 'ضبط «لآدم»', 'كسر اللام ومدّ البدل', 'العلامة الخضراء كسرة اللام في «لآدم». اقرأ اللام مكسورة، وألف «آدم» المعلّمة بالسماوي مد بدل في رواية ورش.', ['لآدم']),
        note(426, 'ترقيق راء «الآخرة»', 'رقّق الراء', 'العلامة الخضراء جزء من ضبط راء «الآخرة». الراء مرققة في هذا الموضع؛ لا تقلب الكسرة إلى حركة أخرى.', ['الآخرة'], [REFS['akhira']]),
        note(478, 'تنوين «قوةً»', 'تنوين فتح وصلاً', 'الدرجتان الخضراوان هنا فتحتا التنوين في «قوةً». عند وصلها بـ«وكانوا» يدغم التنوين في الواو مع الغنة. عند الوقف على تائها المربوطة تقف بالهاء.', ['قوةً']),
        note(543, 'كسرة «القيامة»', 'كسر التاء وصلاً', 'اللون في كسرة التاء المربوطة من «يوم القيامةِ». عند الوصل تنطق التاء مكسورة، وعند الوقف تقف بهاء؛ هذه الكسرة لا تعني إمالة.', ['القيامةِ']),
        note(597, 'كسرة «الناصية»', 'كسر التاء وصلاً', 'اللون في كسرة التاء المربوطة من «بالناصيةِ». أدّ الكسرة عند الوصل، واقف بالهاء عند الوقف؛ لا تستنتج إمالة من هذا اللون.', ['بالناصيةِ']),
    ], 'per-occurrence vowel or documented neighbouring rule'))

