    status['limits'] = ['Completeness is for the printed-sign guides of the pinned twenty PDFs; it is not an all-words or all-turuq certification.', 'Undeclared source shades receive documented local-word explanations, not invented global publisher rules.', 'Native validation is tracked separately from explanatory-guide coverage.']
    for k in ['apkSha256', 'finalNativePreview', 'nativeCorpusViews', 'nativeLimits']: status.pop(k, None)
    write(ROOT / 'reports/qiraat-review-status.json', status)
    write(ROOT / 'reports/qiraat-colour-resolution.json', {'cases': [{'id': rid, 'paint': paint, 'title': value['title'], 'meaning': value['meaning'], 'notes': value['occurrenceNotes'], 'references': value['references'], 'method': value['kind'], 'glyphComponents': len(occurrence_map[rid, paint]['occurrences'])} for (rid, paint), value in replacements.items()], 'allCasesCompleted': True, 'noInventedGlobalShadeRules': True})
    print('PASS: 20 complete printed-sign guides; 33 rare paints / 350 glyph components explained; no placeholder meanings.')

